package com.example.TuVanSinhVien.service;

import com.example.TuVanSinhVien.entity.TaiKhoan;
import com.example.TuVanSinhVien.entity.ThongBao;
import com.example.TuVanSinhVien.repository.ThongBaoRepository;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.time.LocalDateTime;
import java.util.List;
import java.util.UUID;

@Service
public class NotificationService {
    private final ThongBaoRepository thongBaoRepository;

    @Transactional
    public void sendNotification(TaiKhoan recipient, String title, String content, String type, String link) {
        String deduplicationKey = type + "_" + recipient.getMaTK() + "_" + UUID.randomUUID().toString().substring(0, 8);
        ThongBao tb = ThongBao.builder().taiKhoanNhan(recipient).tieuDe(title).noiDung(content).loaiThongBao(type).lienKet(link).daDoc(false).ngayTao(LocalDateTime.now()).khoaChongLap(deduplicationKey).build();
        thongBaoRepository.save(tb);
    }

    @Transactional
    public boolean sendNotificationOnce(TaiKhoan recipient, String deduplicationKey, String title, String content, String type, String link) {
        if (thongBaoRepository.existsByTaiKhoanNhan_MaTKAndKhoaChongLap(recipient.getMaTK(), deduplicationKey)) {
            return false;
        }
        ThongBao notification = ThongBao.builder()
                .taiKhoanNhan(recipient).tieuDe(title).noiDung(content).loaiThongBao(type)
                .lienKet(link).daDoc(false).ngayTao(LocalDateTime.now()).khoaChongLap(deduplicationKey)
                .build();
        thongBaoRepository.save(notification);
        return true;
    }

    public List<ThongBao> getUserNotifications(Integer maTK) {
        return thongBaoRepository.findByTaiKhoanNhan_MaTKOrderByNgayTaoDesc(maTK);
    }

    public long getUnreadCount(Integer maTK) {
        return thongBaoRepository.countByTaiKhoanNhan_MaTKAndDaDocFalse(maTK);
    }

    @Transactional
    public void markAsRead(Long maThongBao, Integer maTK) {
        thongBaoRepository.findByMaThongBaoAndTaiKhoanNhan_MaTK(maThongBao, maTK).ifPresent(tb -> {
            tb.setDaDoc(true);
            thongBaoRepository.save(tb);
        });
    }

    @Transactional
    public void markAllAsRead(Integer maTK) {
        List<ThongBao> unreadList = thongBaoRepository.findByTaiKhoanNhan_MaTKAndDaDocFalseOrderByNgayTaoDesc(maTK);
        for (ThongBao tb : unreadList) {
            tb.setDaDoc(true);
        }
        thongBaoRepository.saveAll(unreadList);
    }

    @java.lang.SuppressWarnings("all")
    @lombok.Generated
    public NotificationService(final ThongBaoRepository thongBaoRepository) {
        this.thongBaoRepository = thongBaoRepository;
    }
}
